68	/** Modifiers are expressed as an amount to add, never as a factor to multiply
69	 *  by, so that they stay additive against their base and so that the integer
70	 *  numerator keeps float artifacts out of the final rounding
71	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / 100;
74	
75	/** Rounds up — premiums round in the MHPCO's favour. */
76	const roundPremium = (amount: number): number => Math.ceil(amount);
77	
78	const COMPONENT_BLOCK_SIZE = 3;
79	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
80	
81	const COMPONENT_TYPES = ["rune", "moonstone"];
82	
83	const isComponent = (item: Item): boolean =>
84	  COMPONENT_TYPES.includes(item.type);
85	
86	const itemBasePremium = (item: Item): number =>
87	  BASE_PREMIUM_BY_TYPE[item.type];
88	
89	const countByType = (items: Item[]): Map<string, number> => {
90	  const counts = new Map<string, number>();
91	  for (const item of items) {
92	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
93	  }
94	  return counts;
95	};
96	
97	/** A block is exactly three alike components, priced as a unit rather than
98	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
99	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
100	  count === COMPONENT_BLOCK_SIZE
101	    ? COMPONENT_BLOCK_BASE_PREMIUM
102	    : count * BASE_PREMIUM_BY_TYPE[type];
103	
104	const sum = (amounts: number[]): number =>
105	  amounts.reduce((total, amount) => total + amount, 0);
106	
107	const policyBasePremium = (items: Item[]): number => {
108	  const mainItems = items.filter((item) => !isComponent(item));
109	  const componentGroups = [...countByType(items.filter(isComponent))];
110	
111	  return (
112	    sum(mainItems.map(itemBasePremium)) +
113	    sum(componentGroups.map(componentGroupBasePremium))
114	  );
115	};
116	
117	interface ItemModifierRule {
118	  appliesTo: (item: Item) => boolean;
119	  percent: number;
120	}
121	
122	/** Every item-scoped modifier, as a rule that either applies to an item or
123	 *  does not. Applicable rules stack. */
124	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
125	  {
126	    appliesTo: (item) => item.cursed === true,
127	    percent: CURSE_SURCHARGE_PERCENT,
128	  },
129	  {
130	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
131	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
132	  },
133	];
134	
135	/** Item-scoped modifiers apply to the affected item's own base premium,
136	 *  not to the policy total. */
137	const itemModifierAmount = (item: Item): number =>
138	  sum(
139	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
140	      percentOf(itemBasePremium(item), rule.percent),
141	    ),
142	  );
143	
144	/** What a policy-wide rule may look at: the customer, plus where this quote
145	 *  sits in the customer's history of contracts. */
146	interface PolicyContext {
147	  customer: Customer;
148	  precedingContracts: number;
149	}
150	
151	interface PolicyModifierRule {
152	  appliesTo: (context: PolicyContext) => boolean;
153	  /** Signed: positive surcharges, negative discounts. */
154	  percent: number;
155	}
156	
157	/** Every policy-wide modifier, as a rule that either applies to a policy or
158	 *  does not. Applicable rules stack. */
159	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
160	  {
161	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
162	    percent: -LOYALTY_DISCOUNT_PERCENT,
163	  },
164	  {
165	    appliesTo: () => true,
166	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
167	  },
168	  {
169	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
170	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
171	  },
172	];
173	
174	/** Policy-wide modifiers apply to the policy base premium — the sum of every
175	 *  item's base premium — not to any single item. */
176	const policyModifierAmount = (
177	  basePremium: number,
178	  context: PolicyContext,
179	): number =>
180	  sum(
181	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
182	      (rule) => percentOf(basePremium, rule.percent),
183	    ),
184	  );
185	
186	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
187	  const basePremium = policyBasePremium(items);
188	  // Every modifier is an amount added to the base premium, not a factor
189	  // compounded onto a running total: item-scoped modifiers take a percentage
190	  // of their own item's base premium, policy-wide ones take a percentage of
191	  // the policy base premium.
192	  const modifierAmounts = [
193	    ...items.map(itemModifierAmount),
194	    policyModifierAmount(basePremium, context),
195	  ];
196	  // The processing fee is added last, after all percentage modifiers.
197	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
198	  return { premium: roundPremium(premium) };
199	};
200	
201	const runStep = (step: Step, context: PolicyContext): StepResult => {
202	  if (step.op === "quote") return quote(step.items, context);
203	  throw new Error(`Unsupported step: ${step.op}`);
204	};
205	
206	export const runScenario = (scenario: Scenario): ScenarioResult => {
207	  let precedingContracts = 0;
208	  const results = scenario.steps.map((step) => {
209	    const result = runStep(step, {
210	      customer: scenario.customer,
211	      precedingContracts,
212	    });
213	    if (step.op === "quote") precedingContracts += 1;
214	    return result;
215	  });
216	  return { results };
217	};
