/** What a step leaves behind for the steps after it. Steps are not
 *  independent: a quote is priced against how many contracts precede it, so
 *  running a scenario threads this state from each step to the next. */
interface ScenarioState {
  customer: Customer;
  precedingContracts: number;
}

const initialState = (customer: Customer): ScenarioState => ({
  customer,
  precedingContracts: 0,
});

/** A step's outcome: what it reports, and the state the next step sees. */
interface StepOutcome {
  result: StepResult;
  state: ScenarioState;
}

const runStep = (step: Step, state: ScenarioState): StepOutcome => {
  if (step.op === "quote")
    return {
      result: quote(step.items, state),
      // Each quote written becomes a preceding contract for the next one.
      state: { ...state, precedingContracts: state.precedingContracts + 1 },
    };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const { results } = scenario.steps.reduce(
    ({ results, state }, step) => {
      const outcome = runStep(step, state);
      return { results: [...results, outcome.result], state: outcome.state };
    },
    { results: [] as StepResult[], state: initialState(scenario.customer) },
  );
  return { results };
};

